#!/bin/bash
#
# Base image for LaunchDarkly Instruqt tracks. Run on a fresh Ubuntu host image
# (Instruqt: Settings -> Host images -> Create image -> terminal), then save it.
#
# REQUIRED sections are marked. Everything after the "Demo app files" marker is
# generated by build-image.sh from ./app and ./app-install.sh.
#
set -euo pipefail
export DEBIAN_FRONTEND=noninteractive
apt-get -y update

# ---- Install tools (terraform + python3 are REQUIRED: terraform runs a python3
#      external data source, modules/workshop-project/sign.py) ----------------
mkdir -p /etc/apt/keyrings
wget -O- https://apt.releases.hashicorp.com/gpg | gpg --dearmor -o /etc/apt/keyrings/hashicorp-archive-keyring.gpg
echo "deb [arch=$(dpkg --print-architecture) signed-by=/etc/apt/keyrings/hashicorp-archive-keyring.gpg] https://apt.releases.hashicorp.com $(lsb_release -cs) main" | tee /etc/apt/sources.list.d/hashicorp.list
apt-get -y update
apt-get -y install unzip jq git curl gnupg ca-certificates terraform vim python3 python3-venv python3-pip

# ---- REQUIRED: clone the Terraform that provisions the learner's project -----
mkdir -p /opt/ld
cd /opt/ld
git clone https://github.com/launchdarkly-labs/ld-workshop-participant.git
cd /opt/ld/ld-workshop-participant
terraform init

# ---- REQUIRED: code-server (the "Code Editor" tab, port 8080, rooted at /opt/ld)
mkdir -p /root/.local/share/code-server/User

cat > /root/.local/share/code-server/User/settings.json <<-SETTINGS
{
    "workbench.colorTheme": "Default Dark+",
    "workbench.startupEditor": "none",
    "security.workspace.trust.enabled": false,
}
SETTINGS

curl -fsSL https://code-server.dev/install.sh | sh

cat <<-UNIT > /etc/systemd/system/code-server.service
[Unit]
Description=Code Server
After=network.target
StartLimitIntervalSec=0

[Service]
Type=simple
Restart=always
RestartSec=1
User=root
ExecStart=/usr/bin/code-server --host 0.0.0.0 --port 8080 --auth none /opt/ld

[Install]
WantedBy=multi-user.target
UNIT

systemctl enable code-server
systemctl start code-server

# code-server --install-extension ms-python.python --user-data-dir /user-data

# ============ Demo app files (generated by build-image.sh from ./app) ============
APP_DIR="${APP_DIR:-/opt/ld/app}"
mkdir -p "$APP_DIR"

mkdir -p "$APP_DIR/."
cat > "$APP_DIR/app.py" <<'__LD_APP_FILE__'
"""
LaunchDarkly demo app for Instruqt tracks.

Server-side flag evaluation with the Python server SDK. The page polls
/api/state every 2 seconds so flag changes show up without a refresh.

Environment (written to /opt/ld/ld.env by the track setup script):
  LD_SDK_KEY        server-side SDK key          (required for flags to work)
  LD_CLIENT_KEY     client-side ID               (exposed to the page for JS SDK demos)
  LD_PROJECT_KEY    project key                  (display only)
  LD_ENV_KEY        environment key, default "test"
  FEATURE_FLAG_KEY  the boolean flag that drives the featured card, default "new-feature"
  PORT              default 8000

Simulate different users with query params, e.g. /?user=alice&country=US&plan=pro
"""
import atexit
import os

import ldclient
from flask import Flask, jsonify, render_template, request
from ldclient import Context
from ldclient.config import Config

SDK_KEY = os.environ.get("LD_SDK_KEY", "")
CLIENT_SIDE_ID = os.environ.get("LD_CLIENT_KEY", "")
PROJECT_KEY = os.environ.get("LD_PROJECT_KEY", "")
ENV_KEY = os.environ.get("LD_ENV_KEY", "test")
FEATURE_FLAG_KEY = os.environ.get("FEATURE_FLAG_KEY", "new-feature")
PORT = int(os.environ.get("PORT", "8000"))

# Custom attributes the page lets you set on the user context. Targeting rules
# in the workshop can key off any of these.
CONTEXT_ATTRIBUTES = ("country", "plan", "email", "beta")

app = Flask(__name__)

client = None
if SDK_KEY:
    ldclient.set_config(Config(SDK_KEY))
    client = ldclient.get()
    atexit.register(client.close)


def build_context(args):
    key = args.get("user") or "workshop-user"
    builder = Context.builder(key).kind("user").name(args.get("name") or key.replace("-", " ").title())
    for attr in CONTEXT_ATTRIBUTES:
        value = args.get(attr)
        if value:
            builder.set(attr, value)
    return builder.build()


def ld_ready():
    return client is not None and client.is_initialized()


def snapshot(context):
    if not ld_ready():
        return {
            "configured": bool(SDK_KEY),
            "initialized": False,
            "flags": {},
            "feature_enabled": False,
        }
    state = client.all_flags_state(context)
    return {
        "configured": True,
        "initialized": True,
        "flags": state.to_values_map(),
        "feature_enabled": client.variation(FEATURE_FLAG_KEY, context, False),
    }


@app.route("/")
def index():
    context = build_context(request.args)
    return render_template(
        "index.html",
        state=snapshot(context),
        context=context.to_dict(),
        project_key=PROJECT_KEY,
        env_key=ENV_KEY,
        client_side_id=CLIENT_SIDE_ID,
        feature_flag_key=FEATURE_FLAG_KEY,
        attributes=CONTEXT_ATTRIBUTES,
    )


@app.route("/api/state")
def api_state():
    context = build_context(request.args)
    data = snapshot(context)
    data["context"] = context.to_dict()
    data["feature_flag_key"] = FEATURE_FLAG_KEY
    return jsonify(data)


@app.route("/healthz")
def healthz():
    return jsonify({"ok": True, "ld_configured": bool(SDK_KEY), "ld_initialized": ld_ready()})


if __name__ == "__main__":
    app.run(host="0.0.0.0", port=PORT, debug=False)
__LD_APP_FILE__

mkdir -p "$APP_DIR/."
cat > "$APP_DIR/requirements.txt" <<'__LD_APP_FILE__'
flask>=3,<4
launchdarkly-server-sdk>=9,<10
__LD_APP_FILE__

mkdir -p "$APP_DIR/templates"
cat > "$APP_DIR/templates/index.html" <<'__LD_APP_FILE__'
<!doctype html>
<html lang="en">
<head>
<meta charset="utf-8">
<title>LaunchDarkly Demo App</title>
<meta name="viewport" content="width=device-width, initial-scale=1">
<style>
  :root { --bg:#0f1117; --card:#181b24; --line:#2a2f3d; --text:#e8eaf0; --muted:#8b91a3; --accent:#405bff; --on:#2ecc71; --off:#e74c3c; }
  * { box-sizing:border-box; }
  body { margin:0; font:15px/1.5 -apple-system,BlinkMacSystemFont,"Segoe UI",Roboto,sans-serif; background:var(--bg); color:var(--text); }
  header { padding:20px 28px; border-bottom:1px solid var(--line); display:flex; justify-content:space-between; align-items:center; flex-wrap:wrap; gap:12px; }
  header h1 { margin:0; font-size:20px; }
  header .meta { color:var(--muted); font-size:13px; }
  main { max-width:960px; margin:0 auto; padding:28px; display:grid; gap:20px; }
  .card { background:var(--card); border:1px solid var(--line); border-radius:10px; padding:20px; }
  .card h2 { margin:0 0 10px; font-size:16px; }
  .banner { padding:14px 18px; border-radius:8px; background:#3a2a10; border:1px solid #7a5a1e; color:#f5d08a; }
  .pill { display:inline-block; padding:2px 10px; border-radius:999px; font-size:12px; font-weight:600; }
  .pill.on { background:rgba(46,204,113,.15); color:var(--on); }
  .pill.off { background:rgba(231,76,60,.15); color:var(--off); }
  #feature { display:none; background:linear-gradient(135deg,#1d2a6b,#3b1d6b); border-color:#5a5cff; }
  #feature.show { display:block; }
  table { width:100%; border-collapse:collapse; }
  th, td { text-align:left; padding:8px 6px; border-bottom:1px solid var(--line); font-size:14px; }
  th { color:var(--muted); font-weight:600; }
  code { background:#0b0d13; padding:2px 6px; border-radius:4px; font-size:13px; }
  form { display:grid; grid-template-columns:repeat(auto-fit,minmax(160px,1fr)); gap:10px; align-items:end; }
  label { font-size:12px; color:var(--muted); display:block; }
  input { width:100%; padding:8px; border-radius:6px; border:1px solid var(--line); background:#0b0d13; color:var(--text); }
  button { padding:9px 14px; border:0; border-radius:6px; background:var(--accent); color:#fff; font-weight:600; cursor:pointer; }
  .muted { color:var(--muted); font-size:13px; }
</style>
</head>
<body>
<header>
  <h1>LaunchDarkly Demo App</h1>
  <div class="meta">
    project <code>{{ project_key or "n/a" }}</code> &middot; environment <code>{{ env_key }}</code>
    &middot; SDK <span id="sdk-status" class="pill {{ 'on' if state.initialized else 'off' }}">{{ 'connected' if state.initialized else 'not connected' }}</span>
  </div>
</header>

<main>
  {% if not state.configured %}
  <div class="banner">
    <strong>Waiting for LaunchDarkly keys.</strong> <code>LD_SDK_KEY</code> is not set yet. The track setup script writes
    <code>/opt/ld/ld.env</code> and restarts this app once your project is provisioned.
  </div>
  {% endif %}

  <section id="feature" class="card {{ 'show' if state.feature_enabled else '' }}">
    <h2>&#10024; New feature unlocked</h2>
    <p>This card is only rendered when the flag <code>{{ feature_flag_key }}</code> evaluates to <code>true</code>
       for the current context. Turn the flag off in LaunchDarkly and watch it disappear.</p>
  </section>

  <section class="card">
    <h2>Current context</h2>
    <p class="muted">Flags are evaluated for this context. Change attributes to test targeting rules.</p>
    <form method="get" action="/">
      <div><label for="user">key</label><input id="user" name="user" value="{{ context.key }}"></div>
      <div><label for="name">name</label><input id="name" name="name" value="{{ context.name or '' }}"></div>
      {% for attr in attributes %}
      <div><label for="{{ attr }}">{{ attr }}</label><input id="{{ attr }}" name="{{ attr }}" value="{{ context[attr] if attr in context else '' }}"></div>
      {% endfor %}
      <div><button type="submit">Evaluate as this user</button></div>
    </form>
  </section>

  <section class="card">
    <h2>All flags for this context</h2>
    <table>
      <thead><tr><th>Flag key</th><th>Value</th></tr></thead>
      <tbody id="flags">
        {% for key, value in state.flags.items() %}
        <tr><td><code>{{ key }}</code></td><td>{{ value | tojson }}</td></tr>
        {% else %}
        <tr><td colspan="2" class="muted">No flags yet. Create one in the LaunchDarkly tab and it will appear here.</td></tr>
        {% endfor %}
      </tbody>
    </table>
    <p class="muted">Updates every 2 seconds via <code>/api/state</code>.</p>
  </section>
</main>

<script>
  // Poll the server for fresh evaluations; the server SDK streams flag changes
  // from LaunchDarkly, so edits in the UI show up here within seconds.
  const params = new URLSearchParams(window.location.search);
  async function refresh() {
    try {
      const res = await fetch('/api/state?' + params.toString(), { cache: 'no-store' });
      const data = await res.json();
      document.getElementById('feature').classList.toggle('show', !!data.feature_enabled);
      const status = document.getElementById('sdk-status');
      status.textContent = data.initialized ? 'connected' : 'not connected';
      status.className = 'pill ' + (data.initialized ? 'on' : 'off');
      const keys = Object.keys(data.flags).sort();
      const rows = keys.map(k => `<tr><td><code>${k}</code></td><td>${JSON.stringify(data.flags[k])}</td></tr>`);
      document.getElementById('flags').innerHTML = rows.length ? rows.join('')
        : '<tr><td colspan="2" class="muted">No flags yet. Create one in the LaunchDarkly tab and it will appear here.</td></tr>';
    } catch (e) { /* server restarting; try again next tick */ }
  }
  setInterval(refresh, 2000);
</script>
</body>
</html>
__LD_APP_FILE__

# ---- Demo app: dependencies + systemd unit -----------------------------------
# Keys arrive at track start: track_scripts/setup-workstation writes /opt/ld/ld.env
# and runs `systemctl restart ld-app`. Until then the app serves a "not configured"
# page, so enabling the unit at image-build time is safe.
cd "$APP_DIR"
python3 -m venv .venv
.venv/bin/pip install --no-cache-dir --upgrade pip
.venv/bin/pip install --no-cache-dir -r requirements.txt

# Vendored JS client SDK (optional, for client-side flag demos; avoids a CDN
# dependency inside the sandbox). Served at /static/ldclient.min.js.
mkdir -p "$APP_DIR/static"
curl -fsSL https://unpkg.com/launchdarkly-js-client-sdk@3/dist/ldclient.min.js -o "$APP_DIR/static/ldclient.min.js"

cat > /etc/systemd/system/ld-app.service <<UNIT
[Unit]
Description=LaunchDarkly demo app
After=network.target
StartLimitIntervalSec=0

[Service]
Type=simple
WorkingDirectory=$APP_DIR
EnvironmentFile=-/opt/ld/ld.env
Environment=PORT=8000
ExecStart=$APP_DIR/.venv/bin/python $APP_DIR/app.py
Restart=always
RestartSec=2
User=root

[Install]
WantedBy=multi-user.target
UNIT

systemctl daemon-reload
systemctl enable ld-app
systemctl start ld-app || true
